 static Label Heading(string title)=>new(){Text=title,Font=new Font("Segoe UI",12,FontStyle.Bold),AutoSize=true,Tag="section"};
 static SettingRow Row(string title,Control value)=>new(title,value);
 static void ConfigureCombo(ComboBox b){b.Width=510;b.DropDownStyle=ComboBoxStyle.DropDownList;}
 sealed record Option(string Id,string Label){public override string ToString()=>Label;}
 static void SelectOption(ComboBox box,string id){for(int i=0;i<box.Items.Count;i++)if(box.Items[i] is Option o&&o.Id==id)box.SelectedIndex=i;}
 async Task RefreshModels(){models=(await manager.Request("list")).Deserialize<List<Model>>()??new();speakerModels=(await manager.Request("speaker-models")).Deserialize<List<SpeakerModel>>()??new();syncing=true;try{void Fill(ComboBox box,IEnumerable<Model> list,string id){box.Items.Clear();box.Items.AddRange(list.Cast<object>().ToArray());for(int i=0;i<box.Items.Count;i++)if(box.Items[i] is Model entry&&entry.Id==id)box.SelectedIndex=i;}Fill(readingModel,new[]{new Model{Id="system",Name="Windows offline voices",Installed=true,Task="tts"}}.Concat(models.Where(m=>m.Task=="tts")),prefs.ReadingModel);Fill(dictationModel,models.Where(m=>m.Task=="stt"&&m.VariantOf==null),prefs.DictationModel);Fill(transcriptionModel,models.Where(m=>m.Task=="stt"&&m.VariantOf==null),prefs.TranscriptionModel);speakerChoice.Items.Clear();speakerChoice.Items.AddRange(speakerModels.Cast<object>().ToArray());for(int i=0;i<speakerChoice.Items.Count;i++)if(speakerChoice.Items[i] is SpeakerModel entry&&entry.Id==prefs.SpeakerModel)speakerChoice.SelectedIndex=i;}finally{syncing=false;}RefreshVoices();RenderModels();await RefreshGpus();_ =WarmReading();}
 void RenderModels(){
  foreach(Control old in modelList.Controls.Cast<Control>().ToArray())old.Dispose();
  foreach(var m in models.Where(m=>m.VariantOf==null)){
   var card=new SettingsCard();card.Add(new Label{Text=m.Name,AutoSize=true,Font=new Font("Segoe UI",13,FontStyle.Bold)});
   string readiness=m.BundleComplete?"Ready offline":m.Installed?"Ready · finish setup":"Not installed";
   card.Add(new Label{Text=$"{readiness} · {(m.BundleSizeMB>0?m.BundleSizeMB:m.SizeMB):0} MB"+(m.Task=="stt"?" · CPU + GPU included":""),AutoSize=true});
   if(!string.IsNullOrEmpty(m.Description))card.Add(new Label{Text=m.Description,AutoSize=true});
   var actions=Bar();actions.Dock=DockStyle.None;
   if(!m.BundleComplete)actions.Controls.Add(AsyncButton(m.Installed?"Complete installation":"Install model",async()=>await ModelOperation(m.Id,"install")));
   if(m.Installed)actions.Controls.Add(AsyncButton("Remove",async()=>await ModelOperation(m.Id,"remove")));
   card.Add(actions);modelList.Controls.Add(card);
  }
  ApplyTheme(modelList);
 }
 async Task RefreshGpus(){
  var devices=(await manager.Request("gpu-devices")).Deserialize<List<GpuDevice>>()??new();availableGpus=devices;syncing=true;
  try{gpuChoice.Items.Clear();gpuChoice.Items.Add(new Option("auto",devices.Count==0?"Automatic · CPU until a supported GPU is available":"Automatic · best supported GPU"));foreach(var gpu in devices.OrderByDescending(g=>g.MemoryMB))gpuChoice.Items.Add(new Option(gpu.Id,$"{gpu.Name} · {gpu.MemoryMB/1024d:0.#} GB"));if(prefs.PreferredGpu!="auto"&&!devices.Any(g=>g.Id==prefs.PreferredGpu))gpuChoice.Items.Add(new Option(prefs.PreferredGpu,"Selected GPU unavailable · automatic mode uses CPU"));SelectOption(gpuChoice,prefs.PreferredGpu);}finally{syncing=false;}
 }
 async Task WarmReading(){if(prefs.ReadingModel=="system"||readingCancel!=null||!models.Any(m=>m.Id==prefs.ReadingModel&&m.Installed))return;try{await readerEngine.Request("warmup-reading",new{model=prefs.ReadingModel});}catch(Exception){/* Reading reports an actionable error if preparation failed. */}}

 async Task ModelOperation(string id,string command){if(working||recorder.Active||recordingFinishing||readingCancel!=null)throw new InvalidOperationException("Stop audio work before changing installed models.");readerEngine.Cancel();modelList.Enabled=false;Toast(command=="install"?"Downloading and verifying model files…":"Removing model…",600);try{await manager.Request(command,new{model=id});await RefreshModels();Toast(command=="install"?"Model downloaded and verified.":"Model removed.");}finally{modelList.Enabled=true;}}
 void RefreshVoices(){syncing=true;try{voices.Items.Clear();if(prefs.ReadingModel=="system")voices.Items.AddRange(systemVoice.GetInstalledVoices().Where(v=>v.Enabled).Select(v=>new Voice{Id=v.VoiceInfo.Name,Name=v.VoiceInfo.Name}).Cast<object>().ToArray());else voices.Items.AddRange((models.FirstOrDefault(m=>m.Id==prefs.ReadingModel)?.Voices??Array.Empty<Voice>()).Cast<object>().ToArray());var selected=prefs.ReadingModel=="system"?prefs.ReadingVoice:prefs.Voices.GetValueOrDefault(prefs.ReadingModel);for(int i=0;i<voices.Items.Count;i++)if(voices.Items[i] is Voice entry&&entry.Id==selected)voices.SelectedIndex=i;if(voices.SelectedIndex<0&&voices.Items.Count>0)voices.SelectedIndex=0;if(voices.SelectedItem is Voice chosen){if(prefs.ReadingModel=="system")prefs.ReadingVoice=chosen.Id;else prefs.Voices[prefs.ReadingModel]=chosen.Id;Save();}}finally{syncing=false;}}
 void CaptureShortcut(Button button,bool reading){
  if(button.Tag is Action oldCapture)oldCapture();
  Native.UnregisterHotKey(Handle,1);Native.UnregisterHotKey(Handle,2);
  button.Text="Press Ctrl / Alt / Shift + a key…";button.Focus();
  KeyEventHandler? capture=null;EventHandler? lost=null;bool finished=false;
  void Finish(){if(finished)return;finished=true;button.KeyDown-=capture;button.LostFocus-=lost;button.Tag=null;button.Text=Native.ShortcutName(reading?prefs.ReadModifiers:prefs.DictateModifiers,reading?prefs.ReadKey:prefs.DictateKey);RegisterShortcuts();}
  capture=(_,e)=>{
   e.SuppressKeyPress=true;if(e.KeyCode==Keys.Escape){Finish();return;}
   if(e.KeyCode is Keys.ControlKey or Keys.ShiftKey or Keys.Menu or Keys.LWin or Keys.RWin)return;
   uint mods=(e.Control?2u:0)|(e.Alt?1u:0)|(e.Shift?4u:0),key=(uint)e.KeyCode;
   if(mods==0){Toast("Include Ctrl, Alt, or Shift with a letter or number.");return;}
   if(mods==(reading?prefs.DictateModifiers:prefs.ReadModifiers)&&key==(reading?prefs.DictateKey:prefs.ReadKey)){Toast("Read and dictation need different shortcuts.");return;}
   int id=reading?1:2;
   if(!Native.RegisterHotKey(Handle,id,mods|0x4000,key)){Toast("That shortcut is in use or reserved by Windows. Choose another.");return;}
   Native.UnregisterHotKey(Handle,id);
   if(reading){prefs.ReadModifiers=mods;prefs.ReadKey=key;}else{prefs.DictateModifiers=mods;prefs.DictateKey=key;}
   Save();Finish();
  };
  lost=(_,_)=>Finish();button.Tag=(Action)Finish;button.KeyDown+=capture;button.LostFocus+=lost;
 }

 bool RegisterShortcuts(){if(!servicesEnabled||quitting||IsDisposed||Disposing)return true;Native.UnregisterHotKey(Handle,1);Native.UnregisterHotKey(Handle,2);bool read=Native.RegisterHotKey(Handle,1,prefs.ReadModifiers|0x4000,prefs.ReadKey),dictate=Native.RegisterHotKey(Handle,2,prefs.DictateModifiers|0x4000,prefs.DictateKey);if(!read||!dictate)Toast("Some shortcuts are already used by Windows or another app. Change them in Settings.",10);return read&&dictate;}
 protected override void WndProc(ref Message m){if(m.Msg==0x0312){if(m.WParam.ToInt32()==1)_ =Safe(ReadSelection);else if(m.WParam.ToInt32()==2)_ =Safe(()=>ToggleDictation());}base.WndProc(ref m);}
 async Task ReadSelection(){
  if(Native.GetForegroundWindow()==Handle){await StartReading();return;}
  await Native.WaitForModifiers();
  // Materialize the existing formats before the target app replaces the clipboard.
  var previous=Clipboard.GetDataObject();var saved=new DataObject();
  if(previous!=null)foreach(var format in previous.GetFormats(false)){var value=previous.GetData(format,false);if(value!=null)saved.SetData(format,false,value);}
  uint before=Native.GetClipboardSequenceNumber(),copied=before;string text;
  Native.Shortcut(0x43);
  try{
   for(int i=0;i<20&&Native.GetClipboardSequenceNumber()==before;i++)await Task.Delay(50);
   copied=Native.GetClipboardSequenceNumber();
   if(copied==before||!Clipboard.ContainsText())throw new InvalidOperationException("No selected text was copied. Select text in the other app, or copy and paste it into Read.");
   text=Clipboard.GetText();
  }finally{
   // Never overwrite a newer copy made while the request was in flight.
   if(copied!=before&&Native.GetClipboardSequenceNumber()==copied){if(previous==null)Clipboard.Clear();else Clipboard.SetDataObject(saved,true);}
  }
  editor.Text=text;ShowSentences();tabs.SelectedIndex=0;await StartReading();
 }
 void Save(){try{prefs.Save();}catch(Exception e){Toast("Preferences were not saved: "+e.Message,12);}}
 void Copy(string text){if(string.IsNullOrEmpty(text))return;Clipboard.SetText(text);}
 async Task Safe(Func<Task> action){try{await action();}catch(OperationCanceledException){}catch(Exception e){overlay.Hide();Toast(e.Message,12);}}
 void Toast(string text,int seconds=7){if(IsDisposed)return;notice.Text=text;noticeUntil=DateTime.UtcNow.AddSeconds(seconds);notice.Visible=true;}
 void Tick(){presentation?.RefreshState();if(hoverNotice)noticeUntil=DateTime.UtcNow.AddSeconds(4);double remaining=(noticeUntil-DateTime.UtcNow).TotalSeconds;if(remaining<=0){notice.Text="";notice.Visible=false;}if(filePlayer.Playing){int index=transcript.Captions.FindIndex(c=>c.Start<=filePlayer.Position&&c.End>filePlayer.Position);if(index>=0&&index<captions.Rows.Count&&!captions.Rows[index].Selected){captions.ClearSelection();captions.Rows[index].Selected=true;}}if(recorder.Active&&recorderTime.Elapsed.TotalSeconds>299)_ =Safe(()=>ToggleDictation());}
 readonly Stopwatch recorderTime=new();
 static void ApplyTheme(Control root)=>WindowsTheme.Apply(root);
 void GroupSettings(){
  var controls=settings.Controls.Cast<Control>().ToArray();settings.Controls.Clear();SettingsCard? card=null;
  var groups=new List<SettingsCard>();var sectionBar=Bar();sectionBar.Padding=new Padding(0,0,0,14);
  foreach(var control in controls){
   if(control is Label title&&Equals(title.Tag,"section")){
    if(title.Text.StartsWith("DAVE")){title.Dispose();continue;}
    card=new SettingsCard();groups.Add(card);settings.Controls.Add(card);
    var target=card;var label=title.Text.StartsWith("Recognition")?"Performance":title.Text=="Global shortcuts"?"Shortcuts":title.Text;
    var button=new ModernButton{Text=label,AutoSize=true};sectionBar.Controls.Add(button);
    button.Click+=(_,_)=>{settings.SuspendLayout();foreach(var group in groups)group.Visible=group==target;foreach(ModernButton tab in sectionBar.Controls){tab.Selected=tab==button;tab.Invalidate();}settings.AutoScrollPosition=Point.Empty;settings.ResumeLayout(true);};
   }
   if(card==null){control.Dispose();continue;}card.Add(control);
  }
  foreach(var group in groups)group.Visible=group==groups[0];
  if(sectionBar.Controls.Count>0)((ModernButton)sectionBar.Controls[0]).Selected=true;
  settings.Parent!.Controls.Add(sectionBar);
 } static void MakeResponsive(FlowLayoutPanel panel){
  void Fit(){int width=Math.Max(100,panel.ClientSize.Width-panel.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-8);foreach(Control item in panel.Controls){item.Width=width;if(item is SettingsCard){item.MinimumSize=new Size(width,0);item.MaximumSize=new Size(width,0);}if(item is Label label){label.AutoSize=true;label.MaximumSize=new Size(width,0);}if(item is FlowLayoutPanel row){row.AutoSize=true;row.WrapContents=true;row.MaximumSize=new Size(width,0);foreach(Control child in row.Controls)if(child is ComboBox)child.Width=Math.Max(120,Math.Min(510,width-24));}}}
  panel.SizeChanged+=(_,_)=>Fit();panel.ControlAdded+=(_,_)=>Fit();Fit();
 }
